UIPlateImage=function(game){Phaser.Image.call(this,game,0,0,'plates');this.ancestor=null;this.created=0;this.digit=0;this.kill();}
UIPlateImage.prototype=Object.create(Phaser.Image.prototype);UIPlateImage.prototype.constructor=UIPlateImage;UIPlateImage.prototype.spawn=function(x,y,digit,flipped,ancestor){this.reset(x,y);this.ancestor=ancestor;this.created=this.game.time.now;this.digit=digit;if(flipped){this.frame=this.digit+10;this.bringToTop();}else{this.anchor.y=1;this.frame=this.digit;this.sendToBack();}}
UIPlateImage.prototype.flip=function(){var topTween=this.game.add.tween(this.scale).to({y:0},UIConstants.SCRAPYARD_FLIP_TIME/2,Phaser.Easing.Sinusoidal.In,true);var bottomTween=this.game.add.tween(this.scale).to({y:1},UIConstants.SCRAPYARD_FLIP_TIME/2,Phaser.Easing.Sinusoidal.Out);topTween.chain(bottomTween);topTween.onComplete.add(function(){this.digit=(this.digit+1)%10;this.frame=this.digit+10;this.anchor.y=0;this.bringToTop();},this);bottomTween.onComplete.add(function(){if(this.ancestor){this.ancestor.remove();}},this);}
UIPlateImage.prototype.remove=function(){this.kill();}